  const eigen = { naam: "Eigen Stichting", primair: "#7a1f3d", accent: "#d98a00", logo: PNG, logoBreedte: 100, logoHoogte: 25 };
  check("Pro: altijd de Subsidie Kompas-huisstijl, wat er ook gekozen is", ["geen", "eigen", "standaard", void 0].every((k) => themaVoorKeuze({ premium: false, huisstijl: eigen, keuze: k }) === SubsidieKompasTheme));
